        divisors = set()
        # Generate all divisors of target
        for i in range(1, int(math.isqrt(target)) + 1):
            if target % i == 0:
                divisors.add(i)
                divisors.add(target // i)
        valid_pairs = []
        for k in divisors:
            q = target // k
            numerator = q - k + 1
            if numerator <= 0:
                continue
            if numerator % 2 != 0:
                continue
            m = numerator // 2
            if m <= 0:
                continue
            valid_pairs.append((m, k))
        # Find the best pair
        best = None
        for m, k in valid_pairs:
            if best is None:
                best = (m, k)
            else:
                if k > best[1]:
                    best = (m, k)
                elif k == best[1]:
                    if m < best[0]:
                        best = (m, k)
        print(f"{best[0]} {best[1]}")

